-- 0065_assist_api: the API's one face of Assist (ASSIST specs 2.3; escalated 11-23 4:06 PM ET).
-- The API runs as plx_api, and 0062/0063 revoke every assist table from it. assist.matter_items
-- is the list's view (open and unverified matters with the basis reading's quote and the
-- handles the door decides): plx_api may SELECT it and INSERT into assist.matter_log (a
-- person's request, line or dismissal, applied by the matters cycle); nothing else of the
-- schema; assist.matters_heartbeat (the newest cycle time) likewise. plx.sql's role (plx_sql_reader) holds nothing of it. Undo: DROP VIEW
-- assist.matter_items; REVOKE the two grants.
DO $view$ BEGIN IF to_regclass('biz.emails') IS NOT NULL AND to_regclass('biz.teams_messages') IS NOT NULL THEN EXECUTE $q$CREATE OR REPLACE VIEW assist.matter_items AS SELECT m.matter_id, m.owner_person, m.kind, m.subject_key, m.sources, m.basis_at, m.title, m.detail, m.next_act, m.due_at, m.state, m.verified_at, m.verify_note, m.plan, m.plan_status, m.plan_reason, m.audiences, m.markings, m.counterpart, m.legacy_item_id, m.opened_at, coalesce((SELECT array_agg(DISTINCT h) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(m.sources->'readings') = 'array' THEN m.sources->'readings' ELSE '[]'::jsonb END) s JOIN assist.readings r ON r.source = s->>0 AND r.message_key = s->>1, unnest(r.handles) h), '{}') AS handles, b.source, b.quote, e.sender, e.subject, t.sender AS tsender FROM assist.matters m LEFT JOIN assist.readings b ON jsonb_typeof(m.sources->'readings') = 'array' AND b.source = m.sources->'readings'->-1->>0 AND b.message_key = m.sources->'readings'->-1->>1 LEFT JOIN LATERAL (SELECT x.sender, x.subject FROM biz.emails x WHERE b.source = 'emails' AND x.handle = b.handles[1] LIMIT 1) e ON true LEFT JOIN LATERAL (SELECT y.sender FROM biz.teams_messages y WHERE b.source = 'teams_messages' AND y.handle = b.handles[1] LIMIT 1) t ON true WHERE m.state IN ('open', 'unverified')$q$; ELSE EXECUTE $q$CREATE OR REPLACE VIEW assist.matter_items AS SELECT m.matter_id, m.owner_person, m.kind, m.subject_key, m.sources, m.basis_at, m.title, m.detail, m.next_act, m.due_at, m.state, m.verified_at, m.verify_note, m.plan, m.plan_status, m.plan_reason, m.audiences, m.markings, m.counterpart, m.legacy_item_id, m.opened_at, coalesce((SELECT array_agg(DISTINCT h) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(m.sources->'readings') = 'array' THEN m.sources->'readings' ELSE '[]'::jsonb END) s JOIN assist.readings r ON r.source = s->>0 AND r.message_key = s->>1, unnest(r.handles) h), '{}') AS handles, b.source, b.quote, NULL::text AS sender, NULL::text AS subject, NULL::text AS tsender FROM assist.matters m LEFT JOIN assist.readings b ON jsonb_typeof(m.sources->'readings') = 'array' AND b.source = m.sources->'readings'->-1->>0 AND b.message_key = m.sources->'readings'->-1->>1 WHERE m.state IN ('open', 'unverified')$q$; END IF; END $view$;
CREATE OR REPLACE VIEW assist.matters_heartbeat AS SELECT max(at) AS last_cycle_at FROM assist.matter_log WHERE matter_id = '_cycle';
REVOKE ALL ON assist.matter_items FROM PUBLIC;
REVOKE ALL ON assist.matters_heartbeat FROM PUBLIC;
REVOKE ALL ON assist.matter_log FROM PUBLIC;
DO $api$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'plx_api') THEN GRANT USAGE ON SCHEMA assist TO plx_api; GRANT SELECT ON assist.matter_items, assist.matters_heartbeat TO plx_api; GRANT INSERT ON assist.matter_log TO plx_api; GRANT USAGE ON SEQUENCE assist.matter_log_seq_seq TO plx_api; END IF; END $api$;
